ey Vault API limits\r\n\r\n## License\r\n\r\nMIT\r\n\n```\n\n### package.json\n```\n{\r\n  \"name\": \"azure-keyvault-config-provider\",\r\n  \"version\": \"1.0.0\",\r\n  \"description\": \"TypeScript configuration provider backed by Azure Key Vault with caching and rotation\",\r\n  \"main\": \"dist/index.js\",\r\n  \"scripts\": {\r\n    \"build\": \"tsc\",\r\n    \"start\": \"npm run build \u0026\u0026 node dist/index.js\",\r\n    \"dev\": \"ts-node src/index.ts\"\r\n  },\r\n  \"keywords\": [\r\n    \"azure\",\r\n    \"keyvault\",\r\n    \"configuration\",\r\n    \"secrets\"\r\n  ],\r\n  \"author\": \"\",\r\n  \"license\": \"MIT\",\r\n  \"dependencies\": {\r\n    \"@azure/keyvault-secrets\": \"^4.8.0\",\r\n    \"@azure/identity\": \"^4.0.1\"\r\n  },\r\n  \"devDependencies\": {\r\n    \"@types/node\": \"^20.11.0\",\r\n    \"typescript\": \"^5.3.3\",\r\n    \"ts-node\": \"^10.9.2\"\r\n  }\r\n}\r\n\n```\n\n### src\\CachedSecretProvider.ts\n```\nimport { SecretProvider, SecretMetadata } from './SecretProvider';\r\n\r\ninterface CacheEntry {\r\n  value: string;\r\n  metadata: SecretMetadata;\r\n  cachedAt: Date;\r\n}\r\n\r\nexport interface CachedSecretProviderConfig {\r\n  expiryWarningDays: number;\r\n}\r\n\r\nexport class CachedSecretProvider {\r\n  private provider: SecretProvider;\r\n  private cache: Map\u003cstring, CacheEntry\u003e;\r\n  private config: CachedSecretProviderConfig;\r\n\r\n  constructor(\r\n    vaultUrl: string,\r\n    config: CachedSecretProviderConfig = { expiryWarningDays: 7 }\r\n  ) {\r\n    this.provider = new SecretProvider(vaultUrl);\r\n    this.cache = new Map();\r\n    this.config = config;\r\n  }\r\n\r\n  /**\r\n   * Bulk-loads a predefined set of required config keys at startup.\r\n   */\r\n  async bulkLoad(secretNames: string[]): Promise\u003cMap\u003cstring, string\u003e\u003e {\r\n    const results = new Map\u003cstring, string\u003e();\r\n\r\n    console.log(`Bulk loading ${secretNames.length} secrets...`);\r\n    for (const name of secretNames) {\r\n      try {\r\n        const value = await this.getSecret(name);\r\n        if (value !== undefined) {\r\n          results.set(name, value);\r\n        }\r\n      } catch (error: any) {\r\n        console.error(`Failed to load secret '${name}':`, error.message);\r\n      }\r\n    }\r\n\r\n    console.log(`Bulk load complete: ${results.size}/${secretNames.length} secrets loaded`);\r\n    return results;\r\n  }\r\n\r\n  /**\r\n   * Retrieves a secret, using cache if available.\r\n   */\r\n  async getSecret(secretName: string): Promise\u003cstring | undefined\u003e {\r\n    const cached = this.cache.get(secretName);\r\n    if (cached) {\r\n      console.log(`Cache hit for '${secretName}'`);\r\n\r\n      // Check if secret is expiring soon and auto-refresh\r\n      if (await this.shouldRefreshDueToExpiry(cached.metadata)) {\r\n        console.log(\r\n          `Secret '${secretName}' is expiring soon, auto-refreshing...`\r\n        );\r\n        return await this.refreshSecret(secretName);\r\n      }\r\n\r\n      return cached.value;\r\n    }\r\n\r\n    console.log(`Cache miss for '${secretName}', fetching from Key Vault...`);\r\n    return await this.refreshSecret(secretName);\r\n  }\r\n\r\n  /**\r\n   * On-demand refresh of an individual key.\r\n   */\r\n  async refreshSecret(secretName: string): Promise\u003cstring | undefined\u003e {\r\n    const metadata = await this.provider.getSecretMetadata(secretName);\r\n    if (!metadata) {\r\n      this.cache.delete(secretName);\r\n      return undefined;\r\n    }\r\n\r\n    this.cache.set(secretName, {\r\n      value: metadata.value,\r\n      metadata,\r\n      cachedAt: new Date(),\r\n    });\r\n\r\n    console.log(`Secret '${secretName}' cached (version: ${metadata.version})`);\r\n    return metadata.value;\r\n  }\r\n\r\n  /**\r\n   * Checks if a secret should be refreshed due to upcoming expiry.\r\n   */\r\n  private async shouldRefreshDueToExpiry(\r\n    metadata: SecretMetadata\r\n  ): Promise\u003cboolean\u003e {\r\n    if (!metadata.expiresOn) {\r\n      return false;\r\n    }\r\n\r\n    const now = new Date();\r\n    const warningDate = new Date(now);\r\n    warningDate.setDate(warningDate.getDate() + this.config.expiryWarningDays);\r\n\r\n    return metadata.expiresOn \u003c= warningDate;\r\n  }\r\n\r\n  /**\r\n   * Gets all cached secrets that are expiring within the warning window.\r\n   */\r\n  async getExpiringSoonSecrets(): Promise\u003cMap\u003cstring, Date\u003e\u003e {\r\n    const expiring = new Map\u003cstring, Date\u003e();\r\n\r\n    for (const [name, entry] of this.cache.entries()) {\r\n      if (entry.metadata.expiresOn) {\r\n        const isExpiring = await this.shouldRefreshDueToExpiry(\r\n          entry.metadata\r\n        );\r\n        if (isExpiring) {\r\n          expiring.set(name, entry.metadata.expiresOn);\r\n        }\r\n      }\r\n    }\r\n\r\n    return expiring;\r\n  }\r\n\r\n  /**\r\n   * Clears the entire cache.\r\n   */\r\n  clearCache(): void {\r\n    this.cache.clear();\r\n    console.log('Cache cleared');\r\n  }\r\n\r\n  /**\r\n   * Removes a specific secret from cache.\r\n   */\r\n  invalidateSecret(secretName: string): void {\r\n    this.cache.delete(secretName);\r\n    console.log(`Secret '${secretName}' invalidated from cache`);\r\n  }\r\n\r\n  /**\r\n   * Gets the underlying provider for direct access when needed.\r\n   */\r\n  getProvider(): SecretProvider {\r\n    return this.provider;\r\n  }\r\n}\r\n\n```\n\n### src\\SecretProvider.ts\n```\nimport { SecretClient, KeyVaultSecret } from '@azure/keyvault-secrets';\r\nimport { DefaultAzureCredential } from '@azure/identity';\r\n\r\nexport interface SecretMetadata {\r\n  name: string;\r\n  value: string;\r\n  version?: string;\r\n  expiresOn?: Date;\r\n  enabled?: boolean;\r\n}\r\n\r\nexport class SecretProvider {\r\n  private client: SecretClient;\r\n\r\n  constructor(vaultUrl: string) {\r\n    const credential = new DefaultAzureCredential();\r\n    this.client = new SecretClient(vaultUrl, credential);\r\n  }\r\n\r\n  /**\r\n   * Retrieves a secret by name. Returns default value if secret doesn't exist.\r\n   */\r\n  async getSecret(\r\n    secretName: string,\r\n    defaultValue?: string\r\n  ): Promise\u003cstring | undefined\u003e {\r\n    try {\r\n      const secret = await this.client.getSecret(secretName);\r\n      return secret.value;\r\n    } catch (error: any) {\r\n      if (error.statusCode === 404) {\r\n        console.warn(\r\n          `Secret '${secretName}' not found, returning default value`\r\n        );\r\n        return defaultValue;\r\n      }\r\n      throw error;\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Retrieves a specific version of a secret.\r\n   */\r\n  async getSecretVersion(\r\n    secretName: string,\r\n    version: string\r\n  ): Promise\u003cstring | undefined\u003e {\r\n    try {\r\n      const secret = await this.client.getSecret(secretName, { version });\r\n      return secret.value;\r\n    } catch (error: any) {\r\n      if (error.statusCode === 404) {\r\n        console.warn(\r\n          `Secret '${secretName}' version '${version}' not found`\r\n        );\r\n        return undefined;\r\n      }\r\n      throw error;\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Retrieves secret metadata including expiry date.\r\n   */\r\n  async getSecretMetadata(secretName: string): Promise\u003cSecretMetadata | null\u003e {\r\n    try {\r\n      const secret = await this.client.getSecret(secretName);\r\n      return {\r\n        name: secret.name,\r\n        value: secret.value || '',\r\n        version: secret.properties.version,\r\n        expiresOn: secret.properties.expiresOn,\r\n        enabled: secret.properties.enabled,\r\n      };\r\n    } catch (error: any) {\r\n      if (error.statusCode === 404) {\r\n        console.warn(`Secret '${secretName}' not found`);\r\n        return null;\r\n      }\r\n      throw error;\r\n    }\r\n  }\r\n\r\n  /**\r\n   * Checks if a secret is expiring within the specified days.\r\n   */\r\n  async isSecretExpiringSoon(\r\n    secretName: string,\r\n    daysBeforeExpiry: number\r\n  ): Promise\u003cboolean\u003e {\r\n    const metadata = await this.getSecretMetadata(secretName);\r\n    if (!metadata || !metadata.expiresOn) {\r\n      return false;\r\n    }\r\n\r\n    const now = new Date();\r\n    const warningDate = new Date(now);\r\n    warningDate.setDate(warningDate.getDate() + daysBeforeExpiry);\r\n\r\n    return metadata.expiresOn \u003c= warningDate;\r\n  }\r\n\r\n  /**\r\n   * Lists all versions of a secret.\r\n   */\r\n  async listSecretVersions(secretName: string): Promise\u003cstring[]\u003e {\r\n    const versions: string[] = [];\r\n    try {\r\n      const propertiesIterator = this.client.listPropertiesOfSecretVersions(\r\n        secretName\r\n      );\r\n      for await (const properties of propertiesIterator) {\r\n        if (properties.version) {\r\n          versions.push(properties.version);\r\n        }\r\n      }\r\n    } catch (error: any) {\r\n      console.warn(`Failed to list versions for secret '${secretName}'`);\r\n    }\r\n    return versions;\r\n  }\r\n}\r\n\n```\n\n### src\\SecretRotationHelper.ts\n```\nimport { SecretClient, DeletedSecret } from '@azure/keyvault-secrets';\r\nimport { DefaultAzureCredential } from '@azure/identity';\r\n\r\nexport interface RotateSecretOptions {\r\n  newValue: string;\r\n  expiresOn?: Date;\r\n  contentType?: string;\r\n  tags?: { [key: string]: string };\r\n}\r\n\r\nexport class SecretRotationHelper {\r\n  private client: SecretClient;\r\n\r\n  constructor(vaultUrl: string) {\r\n    const credential = new DefaultAzureCredential();\r\n    this.client = new SecretClient(vaultUrl, credential);\r\n  }\r\n\r\n  /**\r\n   * Creates a new version of a secret with updated value and expiry date.\r\n   */\r\n  async createNewSecretVersion(\r\n    secretName: string,\r\n    options: RotateSecretOptions\r\n  ): Promise\u003cstring\u003e {\r\n    console.log(`Creating new version for secret '${secretName}'...`);\r\n\r\n    const secret = await this.client.setSecret(secretName, options.newValue, {\r\n      expiresOn: options.expiresOn,\r\n      contentType: options.contentType,\r\n      tags: options.tags,\r\n    });\r\n\r\n    console.log(\r\n      `New version created: ${secret.properties.version} (expires: ${secret.properties.expiresOn})`\r\n    );\r\n    return secret.properties.version || '';\r\n  }\r\n\r\n  /**\r\n   * Rotates a secret by creating a new version.\r\n   */\r\n  async rotateSecret(\r\n    secretName: string,\r\n    options: RotateSecretOptions\r\n  ): Promise\u003cvoid\u003e {\r\n    const version = await this.createNewSecretVersion(secretName, options);\r\n    console.log(`Secret '${secretName}' rotated successfully (version: ${version})`);\r\n  }\r\n\r\n  /**\r\n   * Safely deletes a secret using the long-running delete operation.\r\n   * Returns the deleted secret after the operation completes.\r\n   */\r\n  async deleteSecret(secretName: string): Promise\u003cDeletedSecret\u003e {\r\n    console.log(`Starting delete operation for secret '${secretName}'...`);\r\n\r\n    const deletePoller = await this.client.beginDeleteSecret(secretName);\r\n    const deletedSecret = await deletePoller.pollUntilDone();\r\n\r\n    console.log(\r\n      `Secret '${secretName}' deleted (scheduled purge: ${deletedSecret.properties.scheduledPurgeDate})`\r\n    );\r\n    return deletedSecret;\r\n  }\r\n\r\n  /**\r\n   * Purges a deleted secret permanently.\r\n   * The secret must be deleted first (soft-delete state).\r\n   */\r\n  async purgeDeletedSecret(secretName: string): Promise\u003cvoid\u003e {\r\n    console.log(`Purging deleted secret '${secretName}'...`);\r\n\r\n    await this.client.purgeDeletedSecret(secretName);\r\n\r\n    console.log(`Secret '${secretName}' purged permanently`);\r\n  }\r\n\r\n  /**\r\n   * Complete cleanup: delete and purge a secret.\r\n   * Use this when you need to fully remove a secret for name reuse.\r\n   */\r\n  async deleteAndPurgeSecret(secretName: string): Promise\u003cvoid\u003e {\r\n    console.log(`\\nStarting full cleanup for secret '${secretName}'...`);\r\n\r\n    // Step 1: Delete the secret (long-running operation)\r\n    await this.deleteSecret(secretName);\r\n\r\n    // Step 2: Wait a bit for delete to fully propagate\r\n    console.log('Waiting for delete operation to propagate...');\r\n    await this.sleep(2000);\r\n\r\n    // Step 3: Purge the deleted secret\r\n    await this.purgeDeletedSecret(secretName);\r\n\r\n    console.log(`Full cleanup complete for secret '${secretName}'`);\r\n  }\r\n\r\n  /**\r\n   * Lists all deleted secrets (in soft-delete state).\r\n   */\r\n  async listDeletedSecrets(): Promise\u003cstring[]\u003e {\r\n    const deletedSecrets: string[] = [];\r\n    try {\r\n      const iterator = this.client.listDeletedSecrets();\r\n      for await (const deletedSecret of iterator) {\r\n        deletedSecrets.push(deletedSecret.name);\r\n      }\r\n    } catch (error: any) {\r\n      console.warn('Failed to list deleted secrets:', error.message);\r\n    }\r\n    return deletedSecrets;\r\n  }\r\n\r\n  /**\r\n   * Recovers a deleted secret.\r\n   */\r\n  async recoverDeletedSecret(secretName: string): Promise\u003cvoid\u003e {\r\n    console.log(`Recovering deleted secret '${secretName}'...`);\r\n\r\n    const recoverPoller = await this.client.beginRecoverDeletedSecret(\r\n      secretName\r\n    );\r\n    await recoverPoller.pollUntilDone();\r\n\r\n    console.log(`Secret '${secretName}' recovered successfully`);\r\n  }\r\n\r\n  private sleep(ms: number): Promise\u003cvoid\u003e {\r\n    return new Promise((resolve) =\u003e setTimeout(resolve, ms));\r\n  }\r\n}\r\n\n```\n\n### src\\index.ts\n```\nimport { CachedSecretProvider } from './CachedSecretProvider';\r\nimport { SecretRotationHelper } from './SecretRotationHelper';\r\n\r\nasync function main() {\r\n  // Read vault URL from environment variable\r\n  const vaultUrl = process.env.AZURE_KEYVAULT_URL;\r\n\r\n  if (!vaultUrl) {\r\n    console.error(\r\n      'ERROR: AZURE_KEYVAULT_URL environment variable not set'\r\n    );\r\n    console.log(\r\n      '\\nUsage: Set AZURE_KEYVAULT_URL to your Key Vault URL (e.g., https://my-vault.vault.azure.net/)'\r\n    );\r\n    console.log(\r\n      'Note: This demo requires a running Azure Key Vault and proper authentication (managed identity or Azure CLI login)\\n'\r\n    );\r\n    return;\r\n  }\r\n\r\n  console.log('='.repeat(70));\r\n  console.log('Azure Key Vault Configuration Provider Demo');\r\n  console.log('='.repeat(70));\r\n  console.log(`Vault URL: ${vaultUrl}\\n`);\r\n\r\n  // Initialize cached provider with 7-day expiry warning\r\n  const cachedProvider = new CachedSecretProvider(vaultUrl, {\r\n    expiryWarningDays: 7,\r\n  });\r\n\r\n  // Step 1: Bulk load several config keys at startup\r\n  console.log('\\n--- STEP 1: Bulk Loading Config Keys ---');\r\n  const requiredKeys = [\r\n    'database-connection-string',\r\n    'api-key',\r\n    'storage-account-key',\r\n  ];\r\n\r\n  const loadedSecrets = await cachedProvider.bulkLoad(requiredKeys);\r\n  console.log('\\nLoaded secrets:');\r\n  for (const [name, value] of loadedSecrets.entries()) {\r\n    console.log(`  - ${name}: ${maskSecret(value)}`);\r\n  }\r\n\r\n  // Step 2: Read secrets from cache (should hit cache)\r\n  console.log('\\n--- STEP 2: Reading Secrets from Cache ---');\r\n  for (const key of requiredKeys) {\r\n    const value = await cachedProvider.getSecret(key);\r\n    if (value) {\r\n      console.log(`  ${key}: ${maskSecret(value)}`);\r\n    }\r\n  }\r\n\r\n  // Step 3: Refresh one secret on-demand\r\n  console.log('\\n--- STEP 3: On-Demand Refresh ---');\r\n  const keyToRefresh = 'api-key';\r\n  console.log(`Invalidating '${keyToRefresh}' from cache...`);\r\n  cachedProvider.invalidateSecret(keyToRefresh);\r\n\r\n  const refreshedValue = await cachedProvider.getSecret(keyToRefresh);\r\n  if (refreshedValue) {\r\n    console.log(`Refreshed ${keyToRefresh}: ${maskSecret(refreshedValue)}`);\r\n  }\r\n\r\n  // Step 4: Check for secrets expiring soon\r\n  console.log('\\n--- STEP 4: Checking for Expiring Secrets ---');\r\n  const expiringSecrets = await cachedProvider.getExpiringSoonSecrets();\r\n\r\n  if (expiringSecrets.size \u003e 0) {\r\n    console.log(\r\n      '\\n⚠️  WARNING: The following secrets are expiring within 7 days:'\r\n    );\r\n    for (const [name, expiresOn] of expiringSecrets.entries()) {\r\n      const daysUntilExpiry = Math.ceil(\r\n        (expiresOn.getTime() - Date.now()) / (1000 * 60 * 60 * 24)\r\n      );\r\n      console.log(`  - ${name}: expires ${expiresOn.toISOString()} (${daysUntilExpiry} days)`);\r\n    }\r\n  } else {\r\n    console.log('✓ No secrets expiring within the warning window');\r\n  }\r\n\r\n  // Step 5: Secret rotation demonstration\r\n  console.log('\\n--- STEP 5: Secret Rotation Demo ---');\r\n  const rotationHelper = new SecretRotationHelper(vaultUrl);\r\n  const demoSecretName = 'demo-rotatable-secret';\r\n\r\n  // Create initial version\r\n  console.log(`\\nCreating initial version of '${demoSecretName}'...`);\r\n  const expiryDate = new Date();\r\n  expiryDate.setDate(expiryDate.getDate() + 90); // 90 days from now\r\n\r\n  await rotationHelper.createNewSecretVersion(demoSecretName, {\r\n    newValue: 'initial-secret-value-v1',\r\n    expiresOn: expiryDate,\r\n    contentType: 'text/plain',\r\n    tags: { environment: 'demo', version: 'v1' },\r\n  });\r\n\r\n  // Rotate the secret (create new version)\r\n  console.log(`\\nRotating '${demoSecretName}' with new value...`);\r\n  const newExpiryDate = new Date();\r\n  newExpiryDate.setDate(newExpiryDate.getDate() + 90);\r\n\r\n  await rotationHelper.rotateSecret(demoSecretName, {\r\n    newValue: 'rotated-secret-value-v2',\r\n    expiresOn: newExpiryDate,\r\n    contentType: 'text/plain',\r\n    tags: { environment: 'demo', version: 'v2' },\r\n  });\r\n\r\n  // List all versions\r\n  console.log(`\\nListing all versions of '${demoSecretName}'...`);\r\n  const provider = cachedProvider.getProvider();\r\n  const versions = await provider.listSecretVersions(demoSecretName);\r\n  console.log(`Found ${versions.length} version(s): ${versions.join(', ')}`);\r\n\r\n  // Step 6: Cleanup demonstration (delete and purge)\r\n  console.log('\\n--- STEP 6: Cleanup Demo (Delete \u0026 Purge) ---');\r\n  console.log(\r\n    '\\nNote: This demonstrates the safe delete-and-purge flow.'\r\n  );\r\n  console.log(\r\n    'In production, you typically keep old versions for rollback capability.'\r\n  );\r\n\r\n  try {\r\n    await rotationHelper.deleteAndPurgeSecret(demoSecretName);\r\n  } catch (error: any) {\r\n    console.error(`Cleanup failed: ${error.message}`);\r\n    console.log(\r\n      'This is expected if soft-delete protection is enabled on the vault.'\r\n    );\r\n  }\r\n\r\n  // Summary\r\n  console.log('\\n' + '='.repeat(70));\r\n  console.log('Demo Complete!');\r\n  console.log('='.repeat(70));\r\n  console.log('\\nKey features demonstrated:');\r\n  console.log('  ✓ Bulk loading of config keys at startup');\r\n  console.log('  ✓ In-memory caching with cache hits');\r\n  console.log('  ✓ On-demand secret refresh');\r\n  console.log('  ✓ Expiry warning detection (7-day window)');\r\n  console.log('  ✓ Secret rotation (creating new versions)');\r\n  console.log('  ✓ Safe cleanup (delete + purge with proper waiting)');\r\n  console.log('  ✓ Managed identity authentication (DefaultAzureCredential)');\r\n  console.log('');\r\n}\r\n\r\nfunction maskSecret(value: string): string {\r\n  if (value.length \u003c= 8) {\r\n    return '****';\r\n  }\r\n  return value.substring(0, 4) + '****' + value.substring(value.length - 4);\r\n}\r\n\r\n// Run the demo\r\nmain().catch((error) =\u003e {\r\n  console.error('\\n❌ Fatal error:', error.message);\r\n  if (error.code === 'ENOTFOUND' || error.statusCode === 401) {\r\n    console.log(\r\n      '\\nTroubleshooting:'\r\n    );\r\n    console.log('  1. Verify AZURE_KEYVAULT_URL is correct');\r\n    console.log('  2. Ensure you are authenticated (az login or managed identity)');\r\n    console.log('  3. Check that your identity has proper Key Vault permissions');\r\n    console.log('     Required: \"Get\", \"Set\", \"Delete\", \"Purge\", \"List\" permissions');\r\n  }\r\n  process.exit(1);\r\n});\r\n\n```\n\n### tsconfig.json\n```\n{\r\n  \"compilerOptions\": {\r\n    \"target\": \"ES2020\",\r\n    \"module\": \"commonjs\",\r\n    \"lib\": [\"ES2020\"],\r\n    \"outDir\": \"./dist\",\r\n    \"rootDir\": \"./src\",\r\n    \"strict\": true,\r\n    \"esModuleInterop\": true,\r\n    \"skipLibCheck\": true,\r\n    \"forceConsistentCasingInFileNames\": true,\r\n    \"resolveJsonModule\": true,\r\n    \"declaration\": true,\r\n    \"declarationMap\": true,\r\n    \"sourceMap\": true,\r\n    \"moduleResolution\": \"node\"\r\n  },\r\n  \"include\": [\"src/**/*\"],\r\n  \"exclude\": [\"node_modules\", \"dist\"]\r\n}\r\n\n```\n\n## Reference Answer\n\nNo reference answer provided.\n\n# Review Scoring Rubric\r\n\r\nYou are a senior Azure SDK code reviewer evaluating generated code.\r\n\r\n## General Criteria\r\n\r\nThese general quality criteria ALWAYS apply to every evaluation. You SHOULD actively verify these where possible (e.g., attempt to build the code, check package versions):\r\n\r\n1. **Code Builds** — Does the generated code compile/build without errors? If you have build tools available, attempt to build it.\r\n2. **Latest Package Versions** — Are the Azure SDK packages the latest stable versions? If you have version-check tools available, verify.\r\n3. **Best Practices** — Does it follow Azure SDK best practices? (DefaultAzureCredential, proper disposal, async patterns, etc.)\r\n4. **Error Handling** — Are errors handled properly? Retries? Timeouts?\r\n5. **Code Quality** — Clean, readable, well-structured code?\r\n\r\n## Prompt-Specific Criteria\r\n\r\nIn addition to general criteria, evaluate each prompt-